local exports = {}

local function KHBBSLocationData(data)
    if data.name == nil or data.world == nil or data.type == nil or data.code == nil then
        error("KHBBsLocationData requires a name, world, type and code")
    end
    if data.offset == nil then
        data.offset = nil -- Redundant, but explicit
    end
    return data
end

